const plPlant=(mi,stg,sz)=>{const P=PS[mi%12],PNm=PLN[mi%12],hh=[0,12,28,42,54,60][stg]*Math.min(1.1,P.hs),y=76-hh;
 let o=`<svg viewBox="0 0 100 100" width="${sz}" height="${sz}" role="img" aria-label="${PNm[0]}"><path d="M30 80h40l-5 16H35z" fill="#c07a4f"/><rect x="27" y="76" width="46" height="7" rx="3" fill="#d58f5f"/>`;
 if(stg===0)return o+`<ellipse cx="50" cy="74" rx="4" ry="3" fill="#7a5a2f"/></svg>`;
 o+=`<path d="M50 76 C50 ${76-hh/2} 50 ${y} 50 ${y}" stroke="#5c9b66" stroke-width="${P.n==='sunflower'?4:3}" fill="none" stroke-linecap="round"/>`;
 const lz=P.n==='basil'?1.1:.7;
 if(stg>=1)o+=plLeaf(50,72-hh/3,-150,P.lf,lz*.8,P.lc);
 if(stg>=2)o+=plLeaf(50,68-hh/2.2,-30,P.lf,lz,P.lc);
 if(stg>=3){o+=plLeaf(50,64-hh/1.8,-155,P.lf,lz*1.1,P.lc);if(P.n==='basil'||P.n==='violet')o+=plLeaf(50,70-hh/3,-35,P.lf,lz,P.lc)}
 if(stg===3)o+=`<ellipse cx="50" cy="${y}" rx="3.5" ry="5.5" fill="${P.b==='#fff'?'#e9e2d0':P.b}" stroke="#5c9b66" stroke-width=".8"/>`;
 if(stg===4){o+=plLeaf(50,y+16,25,P.lf,lz,P.lc)+plLeaf(50,y+22,155,P.lf,lz,P.lc);o+=`<ellipse cx="50" cy="${y-4}" rx="6.5" ry="10" fill="${P.b==='#fff'?'#efe9d8':P.b}" stroke="#0002" stroke-width=".8"/><path d="M44 ${y+2} q6 6 12 0" stroke="#5c9b66" stroke-width="2" fill="none"/>`}
 if(stg===5){o+=plLeaf(50,y+16,25,P.lf,lz,P.lc)+plLeaf(50,y+24,155,P.lf,lz,P.lc);o+=P.f(Math.max(y,22))}
 return o+'</svg>'};
const plRec=()=>{const ym=today().slice(0,7),mx=g('plmax',{}),n=plTotal(ym);if(n>(mx[ym]||0)){mx[ym]=n;D.plmax=mx;sv()}return mx};
const plCard=()=>{const ym=today().slice(0,7),mi=+ym.slice(5)-1,mx=plRec(),n=mx[ym]||0,stg=plStage(n),P=PLN[mi%12],seen=g('plseen',{}),grew=(seen[ym]||0)<n;
 setTimeout(()=>{const s=g('plseen',{});if((s[ym]||0)!==n){s[ym]=n;D.plseen=s;sv()}},1500);
 const ks=new Set(Object.keys(mx));Object.keys(g('ach',{})).forEach(d=>ks.add(d.slice(0,7)));const val=k=>Math.max(mx[k]||0,plTotal(k));const past=[...ks].filter(k=>k<ym&&val(k)>0).sort().reverse();
 return `<div class="card" style="text-align:center"><h3>${I('flower')} نبتة إنجازك</h3><div style="position:relative;display:inline-block">${plPlant(mi,stg,140)}${grew&&n?'<svg class="pldrop" viewBox="0 0 24 24" width="22" height="22" style="position:absolute;top:0;left:60px"><path d="M12 3C8 9 6 12 6 15a6 6 0 0012 0c0-3-2-6-6-12z" fill="#6bb6e8"/></svg>':''}</div><div><b>${P[0]}</b> · ${n} من ${PLT[5]}</div>${past.length?`<h3 style="margin-top:10px">حديقة إنجازاتي</h3><div style="display:flex;flex-wrap:wrap;justify-content:center;gap:4px">${past.map(k=>`<div style="font-size:11px">${plPlant(+k.slice(5)-1,plStage(val(k)),60)}<div>${PLN[(+k.slice(5)-1)%12][0]}</div></div>`).join('')}</div>`:''}</div>`};
(()=>{const st=document.createElement('style');st.textContent='@keyframes pld{from{transform:translateY(-14px);opacity:0}to{transform:translateY(40px);opacity:1}}.pldrop{animation:pld .9s ease-in 1}';document.head.appendChild(st)})();
const oHome2=H.home;
H.home=()=>{const h=oHome2(),a=h.indexOf('<div class="g">'),b=h.indexOf('<div class="card"><h3>أولويتي');if(a<0||b<0)return h;return h.slice(0,a)+plCard()+`<button class="btn" style="width:100%;margin:6px 0" onclick="go('secs')">ادخلي لأقسام سكن</button>`+h.slice(b)};
H.secs=()=>{const h=oHome2(),a=h.indexOf('<div class="g">'),b=h.indexOf('<div class="card"><h3>أولويتي');shell('أقسام سكن','');return a<0||b<0?h:h.slice(a,b)};


/* رياضتي: videos (reviewed list, rotates daily), exercise-day flowers, water tracker */
const VEX=[['https://www.youtube.com/watch?v=O5YX5xg8Seg','صفحة BHF الرسمية (British Heart Foundation)','10-minute living room workout','حوالي ١٠ دقايق']];
const VST=[['https://www.nhs.uk/live-well/exercise/strength-and-resistance/body-blast-cool-down/','NHS (الخدمة الصحية البريطانية)','General cool down (10 minutes)','١٠ دقايق']];
const dayNum=()=>{const t=new Date();return Math.floor(Date.UTC(t.getFullYear(),t.getMonth(),t.getDate())/864e5)};
const vidCard=(lab,L)=>{const v=L[0];return `<div class="row" style="display:block"><b>${lab}</b><div dir="ltr" style="text-align:left">${e(v[2])}<br><small style="color:var(--mut)">${e(v[1])}</small></div><a class="btn" href="${v[0]}" target="_blank" rel="noopener noreferrer" style="display:block;text-align:center;text-decoration:none">افتحي الفيديو</a></div>`};
const spVids=()=>`<div class="card"><h3>فيديو النهارده</h3>${vidCard('حركة ١٠ دقايق',VEX)}${vidCard('إطالة ١٠ دقايق (تمارين إطالة، مش يوجا)',VST)}<p class="note">الفيديوهات من جهات رسمية (BHF و NHS) وبتفتح عندهم، ومش بنتحكم فيها. الكلام بالإنجليزي، والمدرّبات بملابس رياضية، وفيه موسيقى خلفية في فيديو الحركة. لو حسيتي بألم أو دوخة وقّفي، وده مش بديل لنصيحة دكتور.</p></div>`;
const spDays=()=>g('spd',{});
window.spTog=d=>{const x=Object.assign({},spDays());if(x[d])delete x[d];else x[d]=1;st('spd',x);render()};
const spFlow='<svg viewBox="0 0 24 24" width="100%" height="100%"><g>'+[0,1,2,3,4].map(i=>`<ellipse cx="12" cy="6.4" rx="3" ry="4.6" fill="#f27ca5" transform="rotate(${i*72} 12 12)"/>`).join('')+'</g><circle cx="12" cy="12" r="2.8" fill="#f7d56b"/></svg>';
const spGrid=()=>{const t=new Date(),y=t.getFullYear(),m=t.getMonth(),n=new Date(y,m+1,0).getDate(),x=spDays(),p=v=>String(v).padStart(2,'0');let h='<div style="display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:4px;width:100%;box-sizing:border-box">';let c=0;for(let d=1;d<=n;d++){const k=y+'-'+p(m+1)+'-'+p(d),on=x[k],fut=d>t.getDate();if(on)c++;h+=`<button class="chip" aria-label="يوم ${d}" ${fut?'disabled':''} onclick="spTog('${k}')" style="padding:0;min-width:0;min-height:0;font-size:15px;border-radius:14px;overflow:hidden;aspect-ratio:1;display:flex;align-items:center;justify-content:center;${d===t.getDate()?'outline:2px solid var(--gr);':''}">${on?'<span style="width:100%;height:100%;display:block">'+spFlow+'</span>':d}</button>`}return `<div class="card"><h3>${I('flower')} أيام رياضتي</h3>${h}</div><p class="note" style="margin:0 6px">تمرنتي ${c} يوم الشهر ده.</p>`+'</div>'.slice(6)};
window.waSet=n=>{const k='wa'+today();st(k,Math.max(0,Math.min(30,n)));render()};
window.waGoal=v=>{const n=Math.round(+v);if(n>=1&&n<=30)st('wagoal',n);render()};
const waCard=()=>{const gl=g('wagoal',8),n=+g('wa'+today(),0);let dr='';for(let i=0;i<Math.max(gl,n);i++)dr+=`<svg viewBox="0 0 24 24" width="28" height="28" style="margin:1px"><path d="M12 3C8 9 6 12 6 15a6 6 0 0012 0c0-3-2-6-6-12z" fill="${i<n?'#6bb6e8':'#dfe9ef'}"/></svg>`;return `<div class="card"><h3>شرب الميه</h3><div style="text-align:center">${dr}</div><div style="text-align:center;margin:6px 0"><b>${n}</b> من ${gl} كوباية</div><button class="btn" onclick="waSet(${n}+1)">كوباية زيادة</button><button class="chip" onclick="waSet(${n}-1)">كوباية أقل</button><label class="note">هدفي في اليوم (كوبايات)</label><input type="number" min="1" max="30" value="${gl}" onchange="waGoal(this.value)"><p class="note">رقم الهدف إنتِ اللي بتحطيه، مش توصية طبية. البيانات على جهازك بس.</p></div>`};
const oSp=H.sport;H.sport=()=>{let h=oSp();h=h.replace(/<div class="card"><h3>فيديو ١٠ دقايق كل يوم<\/h3><div class="ph">[\s\S]*?<\/div>/,'<div class="card" style="display:none"></div>');return spVids()+h+spGrid()+waCard()};


/* حوّاء: pink house-themed interior, logged-cycle circle (no ovulation marks), medication log */
const hwDs=d=>d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');
const hwPd=s=>{const [y,m,d]=s.split('-').map(Number);return new Date(y,m-1,d)};
const hwDiff=(a,b)=>Math.round((Date.UTC(b.getFullYear(),b.getMonth(),b.getDate())-Date.UTC(a.getFullYear(),a.getMonth(),a.getDate()))/864e5);
const hwHeart=(x,y,r,f,sw)=>`<path transform="translate(${x-r} ${y-r*0.95}) scale(${r/12})" d="M12 22C2 15 1 7 6 4.5 9 3 12 5 12 7.5 12 5 15 3 18 4.5 23 7 22 15 12 22Z" fill="${f}" stroke="${sw||'none'}" stroke-width="1"/>`;
window.hcal=()=>'';window.hring=()=>window.hring0();window.hring0=()=>{const l=g('last','');const H0=g('phist',[]).slice().sort();const gaps=[];for(let i=1;i<H0.length;i++){const d=hwDiff(hwPd(H0[i-1]),hwPd(H0[i]));if(d>0)gaps.push(d)}
 const fromLog=gaps.length>0,N=fromLog?Math.round(gaps.reduce((a,b)=>a+b,0)/gaps.length):(+g('cyc',28)||28),P=Math.max(1,Math.min(15,+g('plen',5)||5));
 if(!l)return '<p class="note">اختاري أول يوم في آخر دورة عشان تظهر الدايرة.</p>';
 if(N<15||N>90)return '<p class="note">طول الدورة اللي مكتوب مش منطقي للرسم. راجعي الرقم في إعدادات الدورة.</p>';
 const t0=new Date();t0.setHours(0,0,0,0);const L=hwPd(l),dd=hwDiff(L,t0),pos=dd>=0?dd:-1,inCyc=pos>=0&&pos<N,nxt=new Date(L);nxt.setDate(nxt.getDate()+N);
 const R=118,cr=Math.max(8,Math.min(15,Math.PI*R/N*0.82));let sv='';
 for(let i=0;i<N;i++){const a=-Math.PI/2-2*Math.PI*i/N,x=150+R*Math.cos(a),y=150+R*Math.sin(a),d=i+1,per=d<=P,cur=inCyc&&i===pos;
  sv+=(per?hwHeart(x,y,cr*1.15,'#e0405f'):`<circle cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="${cr}" fill="#fff" stroke="#f4b8cb"/>`)+(cur?`<circle cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="${(cr*1.35).toFixed(1)}" fill="none" stroke="#c2185b" stroke-width="2.2"/>`:'')+`<text x="${x.toFixed(1)}" y="${(y+(per?cr*0.1:0)+cr*0.32).toFixed(1)}" text-anchor="middle" font-size="${Math.round(cr*0.85)}" font-weight="700" fill="${per?'#fff':'#8a2b4d'}">${d}</text>`}
 const nx=nxt.toLocaleDateString('ar-EG',{day:'numeric',month:'long'});
 const mid=inCyc?`<text x="150" y="132" text-anchor="middle" font-size="13" fill="#8a2b4d">إنتِ في اليوم</text><text x="150" y="172" text-anchor="middle" font-size="40" font-weight="800" fill="#c2185b">${pos+1}</text><text x="150" y="192" text-anchor="middle" font-size="12" fill="#8a2b4d">من ${N}</text>`:`<text x="150" y="150" text-anchor="middle" font-size="13" fill="#8a2b4d">عدّى موعد التوقع</text>`;
 return `<svg viewBox="0 0 300 300" width="100%" role="img" aria-label="دايرة أيام الدورة">${sv}${mid}</svg><p style="text-align:center;margin:4px 0"><b>${hwHeart(0,0,0,'none')?'':''}الدورة الجاية متوقعة تقريبًا حوالي ${nx}</b></p><p class="note">تقدير بس. طول الدورة اللي الدايرة مبنية عليه (${N} يوم) ${fromLog?'متوسط دوراتك اللي سجّلتيها':'الرقم اللي كتبتيه في الإعدادات'}، والدورات بتختلف من شهر للتاني. القلوب الحمرا أيام الدورة من أول يوم سجّلتيه.</p>`};
const hwInfo=`<div class="card"><h3>معلومة عامة عن التبويض</h3><p class="note">حسب الـNHS: التبويض صعب تحديده بالظبط، وعند أغلب الستات بيحصل حوالي ١٠ لـ١٦ يوم قبل الدورة الجاية. ده كلام عام ومش بيتحسب على الدايرة بتاعتك، ومش وسيلة لمنع الحمل. وسائل زي حبوب منع الحمل المركّبة بتشتغل أساسًا بإنها بتوقّف التبويض. اسألي دكتورك لو محتاجة معلومة تخصك.<br><a href="https://www.nhs.uk/conditions/periods/fertility-in-the-menstrual-cycle/" target="_blank" rel="noopener noreferrer">مصدر الـNHS</a></p></div>`;
window.hwMed=d=>{const x=Object.assign({},g('medd',{}));if(x[d])delete x[d];else x[d]=1;st('medd',x);render()};
const hwMedCard=()=>{const t=new Date(),y=t.getFullYear(),m=t.getMonth(),n=new Date(y,m+1,0).getDate(),x=g('medd',{}),p=v=>String(v).padStart(2,'0');let h='<div style="display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:4px;width:100%;box-sizing:border-box">';for(let d=1;d<=n;d++){const k=y+'-'+p(m+1)+'-'+p(d),on=x[k],fut=d>t.getDate();h+=`<button class="chip" aria-label="يوم ${d}" ${fut?'disabled':''} onclick="hwMed('${k}')" style="padding:0;min-width:0;min-height:0;font-size:15px;border-radius:14px;overflow:hidden;aspect-ratio:1;display:flex;align-items:center;justify-content:center;${d===t.getDate()?'outline:2px solid #c2185b;':''}">${on?'<svg viewBox="0 0 24 24" width="100%" height="100%"><path d="M12 22C2 15 1 7 6 4.5 9 3 12 5 12 7.5 12 5 15 3 18 4.5 23 7 22 15 12 22Z" fill="#e0405f"/></svg>':d}</button>`}h+='</div>';
 return `<div class="card"><h3>متابعة الدوا (اختياري)</h3><label class="note">اسم الدوا زي ما إنتِ عايزة تكتبيه</label><input maxlength="40" value="${e(g('medn',''))}" onchange="st('medn',this.value.trim())"><p class="note">القلب الأحمر = أخدتيه النهارده (اضغطي على اليوم). ده تسجيل منك بس: مش بنقترح جرعات ولا بنغيّر مواعيد ولا بنقول لو فاتتك جرعة تعملي إيه. اسألي دكتورك أو الصيدلي. البيانات على جهازك بس.</p>${h}</div>`};
