/* ===== owner panel (v6 review): editor = owner account only, server enforces; draft stays on this device; publish raises config v ===== */
const OWNER_EM='mariamreda.work@gmail.com';
const jem=t=>{try{return JSON.parse(atob(t.split('.')[1].replace(/-/g,'+').replace(/_/g,'/'))).email||''}catch(e){return''}};
const isOwner=()=>{try{const S=authS();return !!(S&&S.at&&jem(S.at).toLowerCase()===OWNER_EM)}catch(e){return false}};
const dget=()=>{try{return JSON.parse(localStorage.getItem('sakan_draft')||'null')}catch(e){return null}};
const dset=d=>localStorage.setItem('sakan_draft',JSON.stringify(d));
const baseSecs=()=>SECS.map(x=>[x[0],x[1]]);
const dcur=()=>{let d=dget();if(!d||!d.order){d={labels:Object.assign({},(CFG&&CFG.labels)||{}),hidden:((CFG&&CFG.hidden)||[]).slice(),order:SECS.map(x=>x[0])};if(CFG&&CFG.order&&CFG.order.length)d.order=CFG.order.concat(SECS.map(x=>x[0]).filter(k=>!CFG.order.includes(k)));}return d};
let OWN_MSG='';
const ownRows=()=>{const d=dcur();const all=baseSecs();const nm=k=>(d.labels[k]||(all.find(x=>x[0]===k)||[0,k])[1]);const keys=d.order.filter(k=>all.some(x=>x[0]===k)||d.hidden.includes(k));return keys.map((k,i)=>`<div class="row" style="display:block"><input type="text" id="ol_${k}" value="${nm(k).replace(/"/g,'&quot;')}" style="display:block;width:100%;box-sizing:border-box;margin-bottom:6px" onchange="ownLbl('${k}',this.value)"><div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:6px;align-items:center"><label style="display:flex;gap:6px;align-items:center;justify-content:center"><input type="checkbox" ${d.hidden.includes(k)?'':'checked'} onchange="ownVis('${k}',this.checked)"><span>ظاهر</span></label><button class="btn" style="padding:6px 0" onclick="ownMv('${k}',-1)">↑</button><button class="btn" style="padding:6px 0" onclick="ownMv('${k}',1)">↓</button></div></div>`).join('')};
window.ownLbl=(k,v)=>{const d=dcur();v=(v||'').trim();if(v)d.labels[k]=v;else delete d.labels[k];dset(d);OWN_MSG='اتحفظت كمسودة على الجهاز ده بس.';render()};
window.ownVis=(k,on)=>{const d=dcur();d.hidden=d.hidden.filter(x=>x!==k);if(!on)d.hidden.push(k);dset(d);OWN_MSG='اتحفظت كمسودة على الجهاز ده بس.';render()};
window.ownMv=(k,s)=>{const d=dcur();const i=d.order.indexOf(k),j=i+s;if(i<0||j<0||j>=d.order.length)return;[d.order[i],d.order[j]]=[d.order[j],d.order[i]];dset(d);OWN_MSG='اتحفظت كمسودة على الجهاز ده بس.';render()};
window.ownPrev=()=>{sessionStorage.setItem('sk_prev','1');location.hash='#secs';location.reload()};
window.ownEndPrev=()=>{sessionStorage.removeItem('sk_prev');location.hash='#owner';location.reload()};
window.ownReset=()=>{localStorage.removeItem('sakan_draft');OWN_MSG='المسودة اتمسحت.';render()};
window.ownPub=async()=>{if(!isOwner())return;if(!confirm('تنشري التعديلات لكل المستخدمات؟ هتظهر لهم أول ما يفتحوا التطبيق تاني.'))return;const S=authS();const d=dcur();try{const r0=await fetch(SBU+'/rest/v1/app_config?id=eq.1&select=config',{headers:{apikey:SBK},cache:'no-cache'});const a=await r0.json();const cur=(a&&a[0]&&a[0].config)||{};const nv=Math.max(+cur.v||0,+(CFG&&CFG.v)||0)+1;const nc=Object.assign({},cur,{v:nv,labels:d.labels,hidden:d.hidden,order:d.order});const r=await fetch(SBU+'/rest/v1/app_config?id=eq.1',{method:'PATCH',headers:{apikey:SBK,Authorization:'Bearer '+S.at,'Content-Type':'application/json',Prefer:'return=representation'},body:JSON.stringify({config:nc})});const j=await r.json().catch(()=>null);if(r.ok&&Array.isArray(j)&&j.length===1){OWN_MSG='اتنشرت (نسخة '+nv+'). هتظهر للمستخدمات أول ما يفتحوا التطبيق تاني.'}else{OWN_MSG='النشر ما نفعش. سجلي دخول تاني بإيميل الشغل وجرّبي.'}}catch(e){OWN_MSG='النشر ما نفعش. اتأكدي من النت.'}render()};
H.owner=()=>{if(!isOwner())return `<div class="card"><h3>لوحة التعديل</h3><p class="note">المكان ده لصاحبة التطبيق بس.</p></div>`;return `<div class="card"><h3>لوحة التعديل</h3><p class="note">تغيير أسماء الأقسام وإظهارها وترتيبها. التعديل بيتحفظ مسودة على الجهاز ده، وتقدري تعاينيه قبل النشر، والنشر بيظهر عند الكل أول ما يفتحوا التطبيق تاني. نسخة تجريبية.</p>${ownRows()}<div style="display:grid;gap:8px;margin-top:10px"><button class="btn" onclick="ownPrev()">معاينة</button><button class="btn" onclick="ownPub()">نشر</button><button class="btn" onclick="ownReset()">مسح المسودة</button></div>${OWN_MSG?`<p class="note">${OWN_MSG}</p>`:''}</div>`};
(()=>{const o=H.me;H.me=()=>o()+(isOwner()?`<div class="card"><h3>صاحبة التطبيق</h3><button class="btn" onclick="location.hash='#owner'">لوحة التعديل</button></div>`:'')})();
if(sessionStorage.getItem('sk_prev')){const d=dget();if(d){CFG=Object.assign({},CFG,{labels:d.labels,hidden:d.hidden,order:d.order});SECS=baseSecs().length?SECS:SECS;applyCfg();}const b=document.createElement('div');b.style.cssText='position:fixed;top:0;left:0;right:0;z-index:99;background:#f6c52f;color:#4a2f3b;text-align:center;padding:6px;font-size:14px';b.innerHTML='معاينة بس، مش منشورة. <a href="#" onclick="ownEndPrev();return false">خروج</a>';document.body.appendChild(b)}

/* ===== books: quote photos (device only, resized, capped) ===== */
const BPH_MAX=12, BPH_STORE=3400000;
const lsUsed=()=>{let n=0;try{for(let k=0;k<localStorage.length;k++){const key=localStorage.key(k);n+=key.length+(localStorage.getItem(key)||'').length}}catch(e){}return n};
(()=>{const ob=window.book;window.book=function(i){const h=ob(i);try{const b=bks()[i];if(!b||g('bt'+i,0)!==0)return h;const ph=b.ph||[];const cards=ph.map((p,j)=>`<div class="card q"><img src="${p.d}" alt="صورة اقتباس" style="width:100%;border-radius:12px;display:block"><small>${p.p?'صفحة '+e(p.p):''}</small><button class="btn alt" onclick="bphDel(${i},${j})">مسح الصورة</button></div>`).join('');const add=`<div class="card"><h3>اقتباس من صورة</h3><p class="note">اختاري صورة من الألبوم أو صوّري الصفحة. الصورة بتتصغّر وبتتحفظ على جهازك بس، ومش بتترفع ولا بتتشارك. أقصى عدد ${BPH_MAX} صورة للكتاب الواحد.</p><input id="bpp" placeholder="رقم الصفحة (اختياري)"><input type="file" id="bpf" accept="image/*" onchange="bphAdd(${i},this)">${window._bphMsg?`<p class="note" id="bphm">${window._bphMsg}</p>`:''}<small class="note">${ph.length} من ${BPH_MAX}</small></div>`;const mark='<p class="note">مثال توضيحي';const k=h.lastIndexOf(mark);return k>0?h.slice(0,k)+cards+add+h.slice(k):h+cards+add}catch(x){return h}}})();
window.bphAdd=(i,inp)=>{const f=inp.files&&inp.files[0];if(!f)return;const a=bks(),b=a[i];if(!b)return;b.ph=b.ph||[];if(b.ph.length>=BPH_MAX){window._bphMsg='وصلتي للحد الأقصى ('+BPH_MAX+' صور للكتاب). امسحي صورة قبل ما تضيفي.';render();return}
 const pg=($('#bpp')||{}).value||'';const done=m=>{window._bphMsg=m;render()};
 const fr=new FileReader();fr.onerror=()=>done('الصورة ما اتقرتش. جرّبي صورة تانية.');fr.onload=()=>{const im=new Image();im.onerror=()=>done('الصورة دي مش مدعومة. جرّبي صورة تانية.');im.onload=()=>{try{const M=900,sc=Math.min(1,M/Math.max(im.width,im.height)),w=Math.max(1,Math.round(im.width*sc)),h=Math.max(1,Math.round(im.height*sc)),c=document.createElement('canvas');c.width=w;c.height=h;const x=c.getContext('2d');x.fillStyle='#fff';x.fillRect(0,0,w,h);x.drawImage(im,0,0,w,h);let d=c.toDataURL('image/jpeg',0.72);if(d.length>260000)d=c.toDataURL('image/jpeg',0.5);if(lsUsed()+d.length>BPH_STORE){done('مساحة التخزين على الجهاز قربت تخلص. امسحي صورة قديمة الأول.');return}const a2=bks();a2[i].ph=(a2[i].ph||[]);a2[i].ph.push({d,p:pg});try{st('books',a2)}catch(er){a2[i].ph.pop();done('مساحة التخزين مش كفاية.');return}window._bphMsg='اتضافت الصورة على جهازك.';render()}catch(er){done('حصلت مشكلة في الصورة. جرّبي تاني.')}};im.src=fr.result};fr.readAsDataURL(f)};
window.bphDel=(i,j)=>{if(!confirm('تمسحي الصورة دي؟'))return;const a=bks();if(a[i]&&a[i].ph){a[i].ph.splice(j,1);st('books',a);window._bphMsg='';render()}};

