const GK=Object.keys(GT).sort((p,q)=>q.length-p.length);
const GX=(()=>{
 const tx=(s,m)=>{const t=s.trim();if(GN[t])return s.replace(t,GN[t]);if(!m)return s;if(GT[t])return s.replace(t,GT[t]);let o=s;for(const k of GK){if(k.length>=12&&o.indexOf(k)>=0)o=o.split(k).join(GT[k])}return o};
 const skip=el=>{for(let p=el;p;p=p.parentElement){const t=p.tagName;if(t==='SCRIPT'||t==='STYLE'||t==='TEXTAREA'||t==='INPUT'||(p.hasAttribute&&p.hasAttribute('data-nt')))return true}return false};
 let busy=false;
 const run=root=>{if(busy||!root)return;busy=true;try{const m=isM();
  const w=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);const ns=[];while(w.nextNode())ns.push(w.currentNode);
  const U=[];const lv=(x,d)=>{if(d>6)return;if(typeof x==='string'){if(x.length>=2&&x.length<6000&&x.slice(0,5)!=='data:')U.push(x.trim())}else if(x&&typeof x==='object'){for(const k in x)lv(x[k],d+1)}};try{lv(D,0)}catch(e){}
 const own=t=>U.some(L=>L===t||(t.length>=8&&L.length>t.length&&L.indexOf(t)>=0));
 ns.forEach(n=>{if(!n.parentElement||skip(n.parentElement))return;const o=n.nodeValue,t=o.trim();if(!t||own(t))return;const v=tx(o,m);if(v!==o)n.nodeValue=v});
  (root.querySelectorAll?root.querySelectorAll('[placeholder]'):[]).forEach(el=>{const o=el.getAttribute('placeholder');if(o){const v=tx(o,m);if(v!==o)el.setAttribute('placeholder',v)}});
 }finally{busy=false}};
 return {txt:s=>tx(String(s),isM()),run};
})();
(()=>{let q=0;const go2=()=>{if(q)return;q=requestAnimationFrame(()=>{q=0;GX.run(document.body)})};try{new MutationObserver(go2).observe(document.body,{childList:true,subtree:true})}catch(e){}})();
{const _cf=window.confirm.bind(window),_al=window.alert.bind(window);window.confirm=m=>_cf(GX.txt(m));window.alert=m=>_al(GX.txt(m))}
window.setGen=v=>{st('gen',v);st('gend',1);if(v==='ذكر'&&route()==='hawwa'){location.hash='#health'}render()};
const _hHawwa=H.hawwa;H.hawwa=()=>{if(isM()){setTimeout(()=>{location.hash='#health'},0);return ''}return _hHawwa()};
const _hHealth=H.health;H.health=()=>{const h=_hHealth();return isM()?h.replace(/<button[^>]*go\('hawwa'\)[^>]*>(?:(?!<\/button>)[\s\S])*<\/button>/,''):h};
const genCard=()=>`<div class="card"><h3>أنا</h3><div class="chips">${['أنثى','ذكر'].map(m=>`<button class="chip ${g('gen','')===m?'on':''}" onclick="setGen('${m}')">${m}</button>`).join('')}</div><p class="note">الاختيار بيظبط شكل الكلام والأقسام اللي بتظهر (للرجال مفيش قسم حوّاء وبودكاست الأنوثة). مش بيتبعت لأي حد، وبيتحفظ على جهازك بس، وممكن تغيّره في أي وقت.</p></div>`;
const _hHome2=H.home;H.home=()=>{const h=_hHome2();if(g('gen','')||g('gend',0))return h;return h.replace('</p></div>',`</p></div><div class="card" id="genq"><h3>اختار الأنسب</h3><div class="chips"><button class="chip" onclick="setGen('أنثى')">أنثى</button><button class="chip" onclick="setGen('ذكر')">ذكر</button></div><p class="note">بيظبط شكل الكلام وبعض الأقسام. على جهازك بس، وممكن تغيّره من حسابي.</p></div>`)};
